const canvasPoolBySize=new Map,recentCanvasSizes=new Map;function getCanvasFromPool(s,e){const n=`${s}x${e}`;recentCanvasSizes.set(n,(recentCanvasSizes.get(n)||0)+1);let l=canvasPoolBySize.get(n);if(l||(l=[],canvasPoolBySize.set(n,l)),l.length>0){const o=l.pop();if(o.width>0&&o.height>0)return o;logWarn(t("log.category.canvas"),t("log.msg.discardedCanvas",{w:o.width,h:o.height,key:n}))}const a=document.createElement("canvas");return a.width=s,a.height=e,a.getContext("2d",{willReadFrequently:!0,premultipliedAlpha:!1}),a}function releaseCanvasToPool(s){const e=`${s.width}x${s.height}`;canvasPoolBySize.has(e)||canvasPoolBySize.set(e,[]);const n=canvasPoolBySize.get(e);n.length<5&&n.push(s)}function smartClearCanvasPools(){canvasPoolBySize.forEach((e,n)=>{if(recentCanvasSizes.has(n)){if(e.length>2){const l=e.slice(0,2);e.slice(2).forEach(o=>{o.width=0,o.height=0}),e.length=0,e.push(...l),logLog(t("log.msg.retainedCanvas",{key:n,n:l.length}))}}else{e.forEach(a=>{a.width=0,a.height=0});const l=e.length;e.length=0,logLog(t("log.msg.cleanedUnusedCanvas",{key:n,n:l}))}});for(const[e,n]of canvasPoolBySize.entries())n.length===0&&canvasPoolBySize.delete(e);logLog(t("log.msg.smartCleanDone"))}function preCreateCommonCanvases(){if(recentCanvasSizes.size===0)return;const s=[...recentCanvasSizes.entries()].sort((e,n)=>n[1]-e[1]).slice(0,4);s.forEach(([e])=>{const[n,l]=e.split("x").map(Number);let a=canvasPoolBySize.get(e);for(a||(a=[],canvasPoolBySize.set(e,a));a.length<2;){const o=document.createElement("canvas");o.width=n,o.height=l,o.getContext("2d",{willReadFrequently:!0,premultipliedAlpha:!1}),a.push(o)}}),logLog(t("log.msg.precreateDone",{n:s.length}))}function clearAllCanvasPools(){canvasPoolBySize.forEach(s=>{s.forEach(e=>{e.width=0,e.height=0}),s.length=0}),canvasPoolBySize.clear(),recentCanvasSizes.clear(),logLog(t("log.msg.allCanvasCleared"))}
